typedef unsigned long uint64;

extern "C" void free(void *);
__asm__(".equ free, 0x002AC768");

class pstring {
    uint64 pchunk[4];

public:
    pstring() {
        for (unsigned i = 0; i < 4; ++i)
            pchunk[i] = 0;
    }

    pstring &operator=(const pstring &new_guy) {
        if (&new_guy == this)
            return *this;
        for (unsigned i = 0; i < 4; ++i)
            pchunk[i] = new_guy.pchunk[i];
        return *this;
    }

    bool operator==(const pstring &check_me) const {
        for (unsigned i = 0; i < 4; ++i)
            if (pchunk[i] != check_me.pchunk[i])
                return false;
        return true;
    }

    bool operator>(const pstring &check_me) const {
        for (unsigned i = 0; i < 4; ++i)
            if (pchunk[i] != check_me.pchunk[i])
                return pchunk[i] > check_me.pchunk[i];
        return false;
    }

    bool operator<(const pstring &check_me) const {
        for (unsigned i = 0; i < 4; ++i)
            if (pchunk[i] != check_me.pchunk[i])
                return pchunk[i] < check_me.pchunk[i];
        return false;
    }
};

class stash_index_entry {
    pstring name;
    unsigned file_offset;
    unsigned entry_size;
    unsigned char file_type;
    unsigned char flags;
    unsigned short padding1;
    unsigned char *raw_data;
    int raw_data_size;
    unsigned padding2;
    unsigned padding3;
    unsigned padding4;

public:
    stash_index_entry() {
        raw_data = 0;
        raw_data_size = 0;
        flags = 0;
    }

    ~stash_index_entry() {
        if (raw_data)
            free(raw_data);
        raw_data = 0;
    }

    int compare(stash_index_entry *data) {
        if (name == data->name)
            return 0;
        else if (name < data->name)
            return -1;
        else if (name > data->name)
            return 1;
        return 0;
    }

    void set_name(const pstring &new_name) { name = new_name; }
    friend class stash;
};

template<class T>
class TreeNode {
    TreeNode *l;
    TreeNode *r;
    TreeNode *p;
    T *d;
    char h;

public:
    TreeNode *left() { return l; }
    TreeNode *right() { return r; }
    T *data() { return d; }
    int compare(T *data) { return d != 0 ? d->compare(data) : -1; }
};

template<class T>
class AvlTree {
    TreeNode<T> *root;

public:
    TreeNode<T> *find(T *data) {
        TreeNode<T> *node = root;
        while (node != 0) {
            int comp = node->compare(data);
            if (comp == 0)
                return node;
            if (comp < 0)
                node = node->left();
            else if (comp > 0)
                node = node->right();
            else
                return 0;
        }
        return 0;
    }
};

typedef TreeNode<stash_index_entry> AvlNode;

struct multistash {
    char padding[0x2F0];
    AvlTree<stash_index_entry> index_tree;
    char tail[0x24];
};

class stash {
    stash_index_entry *index;
    bool opened;
    bool eof;
    unsigned fp;
    unsigned max_fp;
    char padding[4];
    pstring fullname;

    static int curstash;
    static multistash substash[11];

public:
    bool open(const pstring &_name);
};

__asm__(".equ _5stash$substash, 0x0046BA84");
__asm__(".equ _5stash$curstash, 0x0046D9C0");

bool stash::open(const pstring &_name)
{
    if (index == 0 || index->name != _name)
    {
        stash_index_entry find_me;
        find_me.name = _name;
        AvlNode *the_node = 0;
        for (int i = 10; i >= 0; i--)
        {
            the_node = substash[i].index_tree.find(&find_me);
            if (the_node)
            {
                curstash = i;
                break;
            }
        }
        if (the_node == 0)
        {
            opened = false;
            eof = false;
            return false;
        }
        stash_index_entry *_index = the_node->data();
        index = _index;
    }
    fp = index->file_offset;
    max_fp = fp + index->entry_size;
    opened = true;
    eof = false;
    fullname = _name;
    return true;
}
